# Code generated by Claude
"""
J0 (a), read only (David 2026-10-25, addendum J): how close would the HELD beaker be to the scene while the robot drives, if it were counted? Today neither the zombie-pose home clearance
(src/stance_checks.StanceChecks.home_clearance, src/home_clearance_map) nor the creep-in sweep (src/bench_stance.creep_blocked, the base footprint only) includes the beaker in the gripper.

For TASK_CFG's stance and the overlay's pick (0.755, 1.145, pedestal 0.10): the arms at home (the zombie pose), the beaker's cylinder (BEAKER_CFG outer diameter and height) standing in the closed gripper
(its axis vertical through the pad centre, the pad centre at the grasp fraction of its height), then the smallest distance of the beaker's geoms to (1) the world (bench, hotplate, every other piece of the
scene), (2) the robot's other parts (right arm, torso, camera box...), at the stance and along the creep-in path (the base moved back along its heading by staging_approach_back_m, 1 cm steps).
Also the beaker's extent in front of the base footprint along the heading. Writes docs/reports/logs/j0_held_clearance.json. Nothing is changed.

    MUJOCO_GL=egl python experiments/j0_held_clearance.py
"""
import json
import math
import os
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
if not os.environ.get("DISPLAY"):
    os.environ.setdefault("MUJOCO_GL", "egl")

import mujoco  # noqa: E402
import numpy as np  # noqa: E402

from src.full_check import FullCheck  # noqa: E402
from src.robot_helpers import arm_ids  # noqa: E402
from src.gripper_geometry import gripper_frame  # noqa: E402
from src.task_config import BEAKER_CFG, PICK_PLACE_CFG, TASK_CFG  # noqa: E402

STANCES = {"TASK_CFG": (*TASK_CFG["staging_xy"], TASK_CFG["staging_yaw"], TASK_CFG["pedestal_q"]), "overlay's pick": (0.755, 1.145, TASK_CFG["staging_yaw"], 0.10)}


def main():
    fc = FullCheck()
    m, chk = fc.model, fc.chk
    d = chk.d
    gf = gripper_frame(m, "left")
    pad_in_tcp = np.asarray(gf["pad_center_in_tcp"], float)
    tcp = m.body("openarm_left_hand_tcp").id
    bk = m.body("task_beaker").id
    jq = m.joint("task_beaker_free").qposadr[0]
    bgeoms = [g for g in range(m.ngeom) if int(m.geom_bodyid[g]) == bk and (m.geom_contype[g] or m.geom_conaffinity[g])]
    bname = lambda g: m.body(int(m.geom_bodyid[g])).name
    hand = set(chk.hand_geoms)
    left_hand_side = {g for g in chk.arm_geoms if bname(g).startswith("openarm_left_") and ("hand" in bname(g) or "finger" in bname(g))}
    world = [g for g in chk.world_geoms if int(m.geom_bodyid[g]) != bk]
    root = m.body("base_link").id

    def under_root(b):
        while b > 0:
            if b == root:
                return True
            b = int(m.body_parentid[b])
        return False

    robot_other = [g for g in range(m.ngeom) if (m.geom_contype[g] or m.geom_conaffinity[g]) and under_root(int(m.geom_bodyid[g])) and g not in left_hand_side and int(m.geom_type[g]) != int(mujoco.mjtGeom.mjGEOM_PLANE)]
    fingers = arm_ids(m, "left")["finger_jnt"]
    ft = np.zeros(6)
    r, H = BEAKER_CFG["outer_diameter"] / 2, BEAKER_CFG["height"]
    frac = PICK_PLACE_CFG["grasp_height_frac"]
    back_m = TASK_CFG.get("staging_approach_back_m", 0.0)
    out = {"beaker": {"diameter_m": 2 * r, "height_m": H, "pad_centre_above_bottom_m": frac * H, "pad_centre_below_top_m": (1 - frac) * H}, "approach_back_m": back_m, "stances": {}}

    def measure(stance):
        chk.place(stance)
        for j in fingers:
            d.qpos[m.jnt_qposadr[j]] = r                                       # the closed gripper on the beaker
        mujoco.mj_kinematics(m, d)
        pad = d.xpos[tcp] + d.xmat[tcp].reshape(3, 3) @ pad_in_tcp
        d.qpos[jq:jq + 7] = [pad[0], pad[1], pad[2] - frac * H, 1, 0, 0, 0]
        mujoco.mj_kinematics(m, d)
        res = {}
        for name, targets in (("world", world), ("robot_other", robot_other)):
            best, pair = 0.3, ""
            for a in bgeoms:
                for b in targets:
                    v = mujoco.mj_geomDistance(m, d, a, b, 0.3, ft)
                    if v < best:
                        best, pair = float(v), f"{m.geom(a).name} vs {bname(b)}:{m.geom(b).name}"
            res[name] = (best, pair)
        return res, pad

    for name, st in STANCES.items():
        x, y, yaw, q = st
        res, pad = measure(st)
        fwd = np.array([math.cos(yaw), math.sin(yaw)])
        rel = pad[:2] - np.array([x, y])
        ahead = float(rel @ fwd)
        lateral = float(rel @ np.array([-fwd[1], fwd[0]]))
        path = {"world": (0.3, "", None), "robot_other": (0.3, "", None)}
        for s in np.arange(back_m, -1e-9, -0.01):
            rs, _ = measure((x - fwd[0] * s, y - fwd[1] * s, yaw, q))
            for k in path:
                if rs[k][0] < path[k][0]:
                    path[k] = (rs[k][0], rs[k][1], float(s))
        out["stances"][name] = {"stance": list(st), "pad_centre_at_home": pad.tolist(), "pad_ahead_of_base_origin_m": ahead, "pad_lateral_m": lateral, "held_at_stance": {k: {"m": v[0], "pair": v[1]} for k, v in res.items()},
                                "held_creep_in_min": {k: {"m": v[0], "pair": v[1], "back_m": v[2]} for k, v in path.items()}}
        print(f"{name} stance {st}: pad centre at home {np.round(pad, 3).tolist()}, {1000 * ahead:.0f} mm ahead of the base origin, {1000 * lateral:.0f} mm lateral")
        for k in ("world", "robot_other"):
            print(f"  held beaker to {k} at the stance {1000 * res[k][0]:.1f} mm ({res[k][1]}); smallest along the creep-in {1000 * path[k][0]:.1f} mm at {path[k][2]} m back ({path[k][1]})")
    tmp = Path("docs/reports/logs/j0_held_clearance.json.tmp")
    tmp.write_text(json.dumps(out, indent=1))
    tmp.replace(Path("docs/reports/logs/j0_held_clearance.json"))


if __name__ == "__main__":
    main()
